use super::*;
use crate::pet_runtime::{rules::{RulePolicy,RuleScope,RuleKind,Rule,DispatchPolicy,Missed,occurrences,scheduled},store::Store};
use std::{fs,os::unix::fs::PermissionsExt,path::PathBuf};use serde_json::json;
struct F{path:PathBuf,policy:RulePolicy}impl F{
 fn new()->Self{
  let path=std::env::temp_dir().join(format!("coucou-rule-succession-{}",nonce().unwrap()));fs::create_dir(&path).unwrap();fs::set_permissions(&path,fs::Permissions::from_mode(0o700)).unwrap();
  let definition=serde_json::from_value(json!({"name":"Bounded daily","intent":"Prepare one response per authorized occurrence","criteria":["Verify actual result"],"schedule":{"kind":"daily","firstDate":"2026-10-24","days":3,"localTime":"09:00","timeZone":"Europe/Lisbon","weekdays":[1,2,3,4,5,6,7],"overlap":"earlier","gap":"skip"},"missed":"skip","graceSeconds":300,"dataScope":"none","limits":{"maxOccurrences":2,"maxModelCalls":2,"maxToolCalls":0,"maxOutputBytes":8192,"occurrenceOutputBytes":4096,"occurrenceTimeoutSeconds":900}})).unwrap();
  let owner=crate::pet_runtime::model::Owner{pet_id:"ai_ollama".into(),provider:"ollama".into(),adapter:"ollama".into(),model_hint:None};let rule=Rule{id:format!("rule-{}","a".repeat(64)),revision:1,owner,state:crate::pet_runtime::rules::State::Draft,created_at:1000,updated_at:1000,definition};
  let schedule={let _s=crate::pet_calendar::TEST_SERIAL.lock().unwrap();crate::pet_calendar::schedule::resolve(&rule.definition.schedule,||true).unwrap()};let first=schedule.slots[0].at.unwrap();let last=schedule.slots.last().unwrap().at.unwrap();
  let policy=RulePolicy{dispatch:None,schema_version:1,scope:RuleScope::BoundedRuleRecurrenceWithoutSelectedData,rule,payment:crate::pet_runtime::admission::Payment::LocalOnly,destination:crate::pet_memory::context_model::Destination::Server{provider:"ollama".into(),endpoint:"http://127.0.0.1:11434/v1/chat/completions".into(),model:"fixture-free".into()},model:"fixture-free".into(),engine_binding:None,policy_revision:"b".repeat(64),descriptor_semantics:"c".repeat(64),schedule,prepared_at:first-60_000,valid_until:last+900_000};assert!(policy.valid());Self{path,policy}
 }
 fn root(&self)->PathBuf{self.path.join("consent")}
 fn authority(&self)->Authority{Authority::ensure(&self.root()).unwrap()}
 fn candidate(&self)->RuleGrant{RuleGrant{schema_version:1,kind:RuleKind::RuleRecurrence,decision_id:nonce().unwrap(),revision:nonce().unwrap(),policy:self.policy.clone(),phase:RulePhase::Active,approved_at:self.policy.prepared_at,updated_at:self.policy.prepared_at,revoked_at:None,reservations:vec![],intent_retirements:vec![],succession:None,revision_authority:None}}
 fn at(&self,i:usize)->u64{self.policy.schedule.slots[i].at.unwrap()}
 fn bytes(&self,g:&RuleGrant)->Vec<u8>{fs::read(self.root().join(format!("{}.json",g.decision_id))).unwrap()}
}impl Drop for F{fn drop(&mut self){let _=fs::remove_dir_all(&self.path);}}

fn issue(f:&F,a:&Authority)->RuleGrant{let g=f.candidate();a.issue_rule(&g,g.approved_at,||true).unwrap();g}
fn revoke(f:&F,a:&Authority,g:&RuleGrant,at:u64){a.revoke_rule("ai_ollama",&f.policy.rule.id,&g.decision_id,at).unwrap();}
fn evidence(g:&crate::pet_runtime::model::Record,p:&RulePolicy,now:u64)->crate::pet_runtime::admission::Evidence{let d=crate::pet_runtime::admission_tests::descriptor(g,now);crate::pet_runtime::admission::Evidence::observe(g,&d,p.policy_revision.clone(),now,false,false).unwrap()}
fn prepare(f:&F,a:&Authority,at:u64)->RuleSuccessionSource{a.prepare_rule_succession("ai_ollama",&f.policy.rule.id,at).unwrap()}
#[test]fn rule_succession_core_old_admission_stays_revoked_and_only_original_remainder_is_admitted(){
 let f=F::new();let a=f.authority();let root=issue(&f,&a);Store::ensure(&f.path.join("goals")).unwrap();let store=Store::existing_verified(&f.path.join("goals"),&f.root()).unwrap().unwrap();let main=crate::chat::Chat::persistent(f.path.join("manual.json"));
 let old=occurrences::admit_at(&store,&a,&f.path.join("contexts"),&main,&root.decision_id,0,||f.at(0),|_|true,|g,n|Ok(evidence(g,&f.policy,n))).unwrap();let old_goal=store.read(&old.goal_id,"ai_ollama").unwrap();a.verify_queued(&old_goal,f.at(0)+1).unwrap();revoke(&f,&a,&root,f.at(0)+2);let before=f.bytes(&root);
 let source=prepare(&f,&a,f.at(0)+3);let successor=source.candidate(&nonce().unwrap(),f.at(0)+3).unwrap();assert_ne!(root.decision_id,successor.decision_id);assert_eq!(root.policy,successor.policy);assert!(successor.reservations.is_empty());assert_eq!(successor.schema_version,6);assert!(a.issue_rule(&successor,f.at(0)+4,||true).is_err());a.succeed_rule(&source,&successor,f.at(0)+4,||true).unwrap();assert_eq!(f.bytes(&root),before);
 assert_eq!(a.verify_queued(&old_goal,f.at(0)+5).err(),Some(Failure::Revoked));assert!(a.reserve_rule_occurrence(&successor.decision_id,&f.policy.hash().unwrap(),0,f.at(0)+5,||true).is_err());assert!(occurrences::admit_at(&store,&a,&f.path.join("contexts"),&main,&successor.decision_id,0,||f.at(0)+5,|_|true,|_,_|panic!("Spent ancestor must be refused before observation")).is_err());
 let status=a.rule_status(&f.policy.rule,true).unwrap();assert_eq!(status.committed_occurrences,1);assert_eq!(status.remaining_occurrences,Some(1));assert_eq!(status.lineage.unwrap().inherited_occurrences,1);assert_eq!(a.rule_prior_allocations(&successor.decision_id).unwrap().len(),1);
 drop(a);let a=Authority::existing(&f.root()).unwrap();assert_eq!(a.rule_decision_for("ai_ollama",&f.policy.rule.id).unwrap(),Some(successor.decision_id.clone()));
 let new=occurrences::admit_at(&store,&a,&f.path.join("contexts"),&main,&successor.decision_id,1,||f.at(1),|_|true,|g,n|Ok(evidence(g,&f.policy,n))).unwrap();let new_goal=store.read(&new.goal_id,"ai_ollama").unwrap();a.verify_queued(&new_goal,f.at(1)+1).unwrap();assert_eq!(new_goal.admissions[0].spec.rule_occurrence.as_ref().unwrap().rule_decision_id,successor.decision_id);
 let status=a.rule_status(&f.policy.rule,true).unwrap();assert_eq!(status.committed_occurrences,2);assert_eq!(status.remaining_occurrences,Some(0));assert_eq!(status.committed_output_bytes,8192);assert!(a.reserve_rule_occurrence(&successor.decision_id,&f.policy.hash().unwrap(),2,f.at(2),||true).is_err());
 let advanced=f.bytes(&successor);let ack=a.succeed_rule(&source,&successor,f.at(1)+2,||true).unwrap();assert_eq!(ack.reservations.len(),1);assert_eq!(f.bytes(&successor),advanced);revoke(&f,&a,&successor,f.at(1)+3);assert!(a.prepare_rule_succession("ai_ollama",&f.policy.rule.id,f.at(1)+4).is_err());assert_eq!(f.bytes(&root),before);
}
#[test]fn rule_succession_core_faults_retain_original_choice_and_never_create_a_second_head(){
 for fault in [Fault::BeforeGrantPublish,Fault::AfterGrantPublish]{
  let f=F::new();let mut a=f.authority();let root=issue(&f,&a);a.reserve_rule_occurrence(&root.decision_id,&f.policy.hash().unwrap(),0,f.at(0),||true).unwrap();revoke(&f,&a,&root,f.at(0)+1);let before=f.bytes(&root);
  let source=prepare(&f,&a,f.at(0)+2);let other=prepare(&f,&a,f.at(0)+2);let chosen=source.candidate(&nonce().unwrap(),f.at(0)+2).unwrap();let conflict=other.candidate(&nonce().unwrap(),f.at(0)+2).unwrap();a.fault=fault;assert!(a.succeed_rule(&source,&chosen,f.at(0)+3,||true).is_err());drop(a);let a=Authority::existing(&f.root()).unwrap();assert!(a.succeed_rule(&other,&conflict,f.at(0)+4,||true).is_err());
  let ack=if !f.root().join(format!("{}.json",chosen.decision_id)).exists(){let reopened=prepare(&f,&a,f.at(0)+5);let same=reopened.candidate(&nonce().unwrap(),f.at(0)+5).unwrap();assert_eq!(same,chosen);a.succeed_rule(&reopened,&same,f.at(0)+6,||true).unwrap()}else{a.succeed_rule(&source,&chosen,f.at(0)+6,||true).unwrap()};
  assert_eq!(ack,chosen);assert_eq!(f.bytes(&root),before);let status=a.rule_status(&f.policy.rule,true).unwrap();assert_eq!(status.pending_artifacts,0);assert_eq!(status.remaining_occurrences,Some(1));assert_eq!(a.rule_inventory_unlocked().unwrap().iter().filter(|(_,_,c)|*c).count(),2);
 }
}
#[test]fn rule_succession_core_stop_revokes_pending_successor_and_old_explicit_id_cannot_claim_success(){
 let f=F::new();let mut a=f.authority();let root=issue(&f,&a);revoke(&f,&a,&root,f.at(0));let source=prepare(&f,&a,f.at(0)+1);let chosen=source.candidate(&nonce().unwrap(),f.at(0)+1).unwrap();a.fault=Fault::BeforeGrantPublish;assert!(a.succeed_rule(&source,&chosen,f.at(0)+2,||true).is_err());a.fault=Fault::None;
 assert_eq!(a.rule_decision_for("ai_ollama",&f.policy.rule.id).unwrap(),Some(chosen.decision_id.clone()));assert!(a.revoke_rule("ai_ollama",&f.policy.rule.id,&root.decision_id,f.at(0)+3).is_err());revoke(&f,&a,&chosen,f.at(0)+3);assert_eq!(a.succeed_rule(&source,&chosen,f.at(0)+4,||true).unwrap().phase,RulePhase::Revoked);
 let cleanup=a.prepare_rule_intent_retirement(&chosen.decision_id).unwrap();let c=cleanup.candidate(&nonce().unwrap(),f.at(0)+5).unwrap();assert_eq!(c.schema_version,6);a.retire_rule_intents(&cleanup,&c,f.at(0)+6,||true).unwrap();assert_eq!(a.rule_status(&f.policy.rule,true).unwrap().pending_artifacts,0);assert_eq!(a.rule_grant(&chosen.decision_id).unwrap().phase,RulePhase::Revoked);
}
#[test]fn rule_succession_core_concurrent_choices_publish_one_head_and_malformed_lineage_fails_closed(){
 let f=F::new();let a=f.authority();let root=issue(&f,&a);revoke(&f,&a,&root,f.at(0));let one=prepare(&f,&a,f.at(0)+1);let two=prepare(&f,&a,f.at(0)+1);let c1=one.candidate(&nonce().unwrap(),f.at(0)+1).unwrap();let c2=two.candidate(&nonce().unwrap(),f.at(0)+1).unwrap();let barrier=std::sync::Arc::new(std::sync::Barrier::new(2));let at=f.at(0)+2;
 let mut handles=vec![];for(s,c)in [(one,c1.clone()),(two,c2.clone())]{let path=f.root();let b=barrier.clone();handles.push(std::thread::spawn(move||{let a=Authority::existing(&path).unwrap();b.wait();a.succeed_rule(&s,&c,at,||true).is_ok()}));}assert_eq!(handles.into_iter().map(|h|h.join().unwrap()).filter(|ok|*ok).count(),1);
 let selected=a.rule_decision_for("ai_ollama",&f.policy.rule.id).unwrap().unwrap();let other=if selected==c1.decision_id{c2}else{c1};a.publish_rule(&other,true,||Ok(())).unwrap();assert!(a.rule_status(&f.policy.rule,true).is_err());assert!(a.rule_prior_allocations(&selected).is_err());assert!(a.reserve_rule_occurrence(&selected,&f.policy.hash().unwrap(),0,f.at(0)+3,||true).is_err());
 // An orphan with a missing predecessor has no path from its claimed root.
 fs::remove_file(f.root().join(format!("{}.json",other.decision_id))).unwrap();let mut bad=other;bad.succession.as_mut().unwrap().generation=2;bad.succession.as_mut().unwrap().predecessor_decision_id=nonce().unwrap();assert!(bad.valid());a.publish_rule(&bad,true,||Ok(())).unwrap();assert!(a.rule_decision_for("ai_ollama",&f.policy.rule.id).is_err());
 fs::remove_file(f.root().join(format!("{}.json",bad.decision_id))).unwrap();let mut x=bad.clone();let mut y=bad;x.decision_id=nonce().unwrap();y.decision_id=nonce().unwrap();x.succession.as_mut().unwrap().predecessor_decision_id=y.decision_id.clone();y.succession.as_mut().unwrap().predecessor_decision_id=x.decision_id.clone();y.succession.as_mut().unwrap().generation=3;assert!(x.valid()&&y.valid());a.publish_rule(&x,true,||Ok(())).unwrap();a.publish_rule(&y,true,||Ok(())).unwrap();assert!(a.rule_decision_for("ai_ollama",&f.policy.rule.id).is_err());
}
#[test]fn rule_succession_core_metadata_progress_preserves_commitment_identity_and_physical_owner(){
 let mut f=F::new();f.policy.dispatch=Some(DispatchPolicy::bounded());f.policy.schema_version=2;f.policy.scope=RuleScope::BoundedAutomaticRuleRecurrenceWithoutSelectedData;let a=f.authority();let mut root=f.candidate();root.schema_version=root.required_version();a.issue_rule(&root,root.approved_at,||true).unwrap();let r=a.reserve_rule_occurrence(&root.decision_id,&f.policy.hash().unwrap(),0,f.at(0),||true).unwrap();let owned=a.begin_owned_rule_probe(&root.decision_id,&r.occurrence_id,f.at(0),||true).unwrap();revoke(&f,&a,&root,f.at(0)+1);let source=prepare(&f,&a,f.at(0)+2);let chosen=source.candidate(&nonce().unwrap(),f.at(0)+2).unwrap();a.succeed_rule(&source,&chosen,f.at(0)+3,||true).unwrap();assert!(owned.current(&a));assert!(crate::pet_runtime::native_owner::EndedOperation::capture(&a,owned.probe().owner.as_ref().unwrap()).is_err());
 let before=a.rule_grant(&root.decision_id).unwrap().commitments_hash().unwrap();a.finish_rule_probe(&root.decision_id,&r.occurrence_id,owned.probe(),false,f.at(0)+4).unwrap();assert_eq!(before,a.rule_grant(&root.decision_id).unwrap().commitments_hash().unwrap());assert_eq!(a.succeed_rule(&source,&chosen,f.at(0)+5,||true).unwrap(),chosen);assert_eq!(a.rule_status(&f.policy.rule,true).unwrap().remaining_occurrences,Some(1));
 let store=Store::ensure(&f.path.join("goals")).unwrap();let prior=a.rule_prior_allocations(&chosen.decision_id).unwrap();assert_eq!(scheduled::due(&chosen,&prior,0,&store,f.at(0)+20).unwrap(),None);assert_eq!(scheduled::due(&chosen,&prior,0,&store,f.at(1)+1).unwrap(),Some(1));drop(owned);
}
#[test]fn rule_succession_core_native_source_change_before_publication_requires_a_fresh_review(){
 let mut f=F::new();f.policy.dispatch=Some(DispatchPolicy::bounded());f.policy.schema_version=2;f.policy.scope=RuleScope::BoundedAutomaticRuleRecurrenceWithoutSelectedData;let a=f.authority();let mut root=f.candidate();root.schema_version=root.required_version();a.issue_rule(&root,root.approved_at,||true).unwrap();let r=a.reserve_rule_occurrence(&root.decision_id,&f.policy.hash().unwrap(),0,f.at(0),||true).unwrap();let owned=a.begin_owned_rule_probe(&root.decision_id,&r.occurrence_id,f.at(0),||true).unwrap();revoke(&f,&a,&root,f.at(0)+1);
 let source=prepare(&f,&a,f.at(0)+2);let chosen=source.candidate(&nonce().unwrap(),f.at(0)+2).unwrap();let digest=a.rule_grant(&root.decision_id).unwrap().commitments_hash().unwrap();a.finish_rule_probe(&root.decision_id,&r.occurrence_id,owned.probe(),false,f.at(0)+3).unwrap();assert_eq!(digest,a.rule_grant(&root.decision_id).unwrap().commitments_hash().unwrap());assert!(a.succeed_rule(&source,&chosen,f.at(0)+4,||true).is_err());assert!(!f.root().join(format!("{}.json",chosen.decision_id)).exists());assert!(owned.current(&a));
 let fresh=prepare(&f,&a,f.at(0)+5);assert_ne!(fresh.hash,source.hash);let new=fresh.candidate(&nonce().unwrap(),f.at(0)+5).unwrap();a.succeed_rule(&fresh,&new,f.at(0)+6,||true).unwrap();assert_eq!(a.rule_status(&f.policy.rule,true).unwrap().remaining_occurrences,Some(1));assert_eq!(a.rule_grant(&root.decision_id).unwrap().reservations[0].readiness[0].observed,Some(false));
}
#[test]fn rule_succession_core_refuses_forged_source_expiry_cancellation_pending_metadata_and_history(){
 let f=F::new();let mut a=f.authority();let root=issue(&f,&a);a.fault=Fault::BeforeGrantPublish;assert!(a.reserve_rule_occurrence(&root.decision_id,&f.policy.hash().unwrap(),0,f.at(0),||true).is_err());a.fault=Fault::None;revoke(&f,&a,&root,f.at(0)+1);assert!(a.prepare_rule_succession("ai_ollama",&f.policy.rule.id,f.at(0)+2).is_err());let retirement=a.prepare_rule_intent_retirement(&root.decision_id).unwrap();let data=retirement.candidate(&nonce().unwrap(),f.at(0)+2).unwrap();a.retire_rule_intents(&retirement,&data,f.at(0)+3,||true).unwrap();
 let source=prepare(&f,&a,f.at(0)+4);let chosen=source.candidate(&nonce().unwrap(),f.at(0)+4).unwrap();let before=f.bytes(&root);assert!(a.succeed_rule(&source,&chosen,f.at(0)+5,||false).is_err());let mut forged=chosen.clone();forged.succession.as_mut().unwrap().source_hash="f".repeat(64);assert!(forged.valid());assert!(a.succeed_rule(&source,&forged,f.at(0)+5,||true).is_err());assert!(a.succeed_rule(&source,&chosen,f.policy.valid_until,||true).is_err());assert!(a.prepare_rule_succession("ai_ollama",&f.policy.rule.id,f.policy.valid_until).is_err());assert_eq!(before,f.bytes(&root));
 let review=restoration::Review::capture(&f.root(),&f.path.join("goals"),&"d".repeat(64),||Ok(())).unwrap();let hash=review.fingerprint().unwrap();review.apply(&hash,||Ok(())).unwrap();let restored=Authority::existing(&f.root()).unwrap();assert!(restored.prepare_rule_succession("ai_ollama",&f.policy.rule.id,f.at(0)+5).is_err());assert!(restored.succeed_rule(&source,&chosen,f.at(0)+5,||true).is_err());assert_eq!(before,f.bytes(&root));
}
