#[test]#[ignore]fn rule_succession_native_preservation_fixture(){
 let Ok(raw)=std::env::var("COUCOU_SUCCESSION_FIXTURE_NATIVE")else{return;};let target=PathBuf::from(raw);assert!(target.is_absolute()&&!target.is_symlink());assert_eq!(fs::read(target.join(".qa-succession-profile")).unwrap(),b"coucou-generated-succession-preservation-only");
 let config=target.join("config/coucou");let data=target.join("data/coucou");for path in [&config,&data]{assert!(!path.exists());fs::create_dir_all(path).unwrap();fs::set_permissions(path,fs::Permissions::from_mode(0o700)).unwrap();}
 fs::write(config.join("settings.json"),serde_json::to_vec(&json!({"mainPill":"ai_ollama","activeIntegrations":["ai_ollama"],"chatProvider":"ollama","chatModels":{"ollama":"fixture-free"},"ollamaUrl":"http://127.0.0.1:1","lmstudioUrl":"","autostart":false,"phoneLink":false,"phoneRelay":false,"hooksInstalled":false,"planRelayInstalled":false})).unwrap()).unwrap();fs::set_permissions(config.join("settings.json"),fs::Permissions::from_mode(0o600)).unwrap();
 let address=std::env::var("DBUS_SESSION_BUS_ADDRESS").unwrap();let native_owner=dbus::blocking::Connection::new_address(&address).unwrap();assert_eq!(native_owner.request_name("fr.louisraille.coucou.dev.SingleInstance",false,false,true).unwrap(),dbus::blocking::stdintf::org_freedesktop_dbus::RequestNameReply::PrimaryOwner);let layout=crate::pet_data::Layout::new(config,data).unwrap();let(payload,_)=crate::pet_data::fixture_publish_profile(&address,"fr.louisraille.coucou.dev",layout).unwrap();assert!(payload.starts_with(&target));std::hint::black_box(&native_owner);
 let f=F::new();let mut a=Authority::ensure(&payload.join("pet-runtime-consent-v1")).unwrap();let root=issue(&f,&a);a.reserve_rule_occurrence(&root.decision_id,&f.policy.hash().unwrap(),0,f.at(0),||true).unwrap();revoke(&f,&a,&root,f.at(0)+1);let source=prepare(&f,&a,f.at(0)+2);let chosen=source.candidate(&nonce().unwrap(),f.at(0)+2).unwrap();a.succeed_rule(&source,&chosen,f.at(0)+3,||true).unwrap();a.reserve_rule_occurrence(&chosen.decision_id,&f.policy.hash().unwrap(),1,f.at(1),||true).unwrap();
 a.fault=Fault::BeforeGrantPublish;assert!(a.revoke_rule("ai_ollama",&f.policy.rule.id,&chosen.decision_id,f.at(1)+1).is_err());a.fault=Fault::None;revoke(&f,&a,&chosen,f.at(1)+1);let retirement=a.prepare_rule_intent_retirement(&chosen.decision_id).unwrap();let reduced=retirement.candidate(&nonce().unwrap(),f.at(1)+2).unwrap();assert_eq!(reduced.schema_version,6);a.retire_rule_intents(&retirement,&reduced,f.at(1)+3,||true).unwrap();let status=a.rule_status(&f.policy.rule,false).unwrap();assert_eq!(status.committed_occurrences,2);assert_eq!(status.phase,"revoked");assert_eq!(status.remaining_occurrences,Some(0));
 let book=payload.join("pet-rules.json");fs::write(&book,serde_json::to_vec(&json!({"version":1,"generation":1,"rules":[f.policy.rule]})).unwrap()).unwrap();fs::set_permissions(book,fs::Permissions::from_mode(0o600)).unwrap();
 fs::write(target.join("NATIVE-FIXTURE.json"),serde_json::to_vec(&json!({"schemaVersion":1,"kind":"generatedHistoricalDataOnly","sourceNativeTest":"rule_succession_native_preservation_fixture","rootDecisionId":root.decision_id,"successorDecisionId":chosen.decision_id,"originalPolicy":f.policy,"status":status,"nativePublication":true,"modelCalls":0,"humanApproval":false,"actualNativeWindow":false,"goalComplete":false})).unwrap()).unwrap();
}
